"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisHeroContent } from "./components/hero-sections/content";
import View7 from "./components/hero-sections/variants/12-split-demo";
const views={"split-demo":View7};
export type { ArtemisHeroContent, ArtemisHeroCta, ArtemisHeroForm, ArtemisHeroImage, ArtemisHeroLink, ArtemisHeroLogo, ArtemisHeroNav, ArtemisHeroPrompt } from "./components/hero-sections/content";
export interface ArtemisHeroSectionsProps {className?:string;variant?:"split-demo"; /** The words on the hero; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisHeroContent>;}
export function ArtemisHeroSections({className,variant="split-demo",content}:ArtemisHeroSectionsProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a link, and where it goes. */
export interface ArtemisHeroLink {
  label: string;
  href: string;
}

/** The words on a button, and where it links. */
export interface ArtemisHeroCta {
  label: string;
  /** Where it links. analytics-flow and ai-teammates use only the label: their buttons scroll to the demo and open its brief. */
  href?: string;
}

/** An image, and the words that stand in for it (empty when it only decorates). */
export interface ArtemisHeroImage {
  src: string;
  alt: string;
}

/** A customer or partner, shown by name. */
export interface ArtemisHeroLogo {
  name: string;
}

/** The bar across the top of the layouts that have their own. */
export interface ArtemisHeroNav {
  /** The name beside the logo mark, and where it links. Every layout with a bar. */
  brand: ArtemisHeroLink;
  /** Links in the bar and its mobile menu. Every layout with a bar. */
  links: ArtemisHeroLink[];
  /** The sign-in link. decision-spectrum, ai-marketplace and signal-aurora; left out, they show none. */
  login?: ArtemisHeroLink;
  /** The button at the end of the bar. voice-mobile, decision-spectrum, defi-routing and ai-marketplace; left out, they show none. */
  cta?: ArtemisHeroLink;
  /** The button in the open mobile menu, where its words differ from `cta`. voice-mobile, decision-spectrum, defi-routing and ai-marketplace; left out, the menu shows `cta`. */
  menuCta?: ArtemisHeroLink;
}

/** An email field and its button. */
export interface ArtemisHeroForm {
  /** The field's label, read by screen readers. */
  label: string;
  /** The hint in the empty field. */
  placeholder: string;
  /** The button's words. */
  submit: string;
}

/** A box where visitors describe what they need. */
export interface ArtemisHeroPrompt {
  /** The small title over the box. */
  title: string;
  /** The field's name, read by screen readers. */
  label: string;
  /** Example requests that take turns in the empty box. */
  examples: string[];
  /** The send button's name, read by screen readers. */
  submit: string;
  /** The line shown once a request is sent. */
  confirmation: string;
  /** Requests under the box; choosing one fills it in. */
  suggestions: string[];
}

/** The words on an Artemis hero. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisHeroContent {
  /** The hero's own bar with the brand, links and buttons. voice-mobile, decision-spectrum, defi-routing, ai-marketplace and signal-aurora. */
  nav?: ArtemisHeroNav;
  /** A short line over the headline. All layouts but decision-spectrum. */
  badge?: string;
  /** Small faces beside the badge; screen readers skip them. split-demo. */
  avatars?: ArtemisHeroImage[];
  /** The headline, or its first part where a layout splits it. All layouts. */
  headline: string;
  /** The rest of the headline. analytics-flow mutes it and decision-spectrum sets it bolder; ai-teammates, voice-mobile, defi-routing and ai-marketplace start it on a new line; signal-aurora and split-demo run it on after the headline. It goes with `headline`: give a headline without it and the headline shows on its own; leave both out to keep the layout's own. */
  headlineAccent?: string;
  /** The paragraph under the headline. All layouts. */
  subhead: string;
  /** The main button. analytics-flow, ai-teammates, voice-mobile, decision-spectrum, signal-aurora and split-demo. */
  cta?: ArtemisHeroCta;
  /** The second button. analytics-flow, ai-teammates, voice-mobile, decision-spectrum and split-demo. */
  secondaryCta?: ArtemisHeroCta;
  /** An email field and its button, in place of buttons. defi-routing. */
  form?: ArtemisHeroForm;
  /** A box for describing what you need, in place of buttons. ai-marketplace. */
  prompt?: ArtemisHeroPrompt;
  /** A short line under the buttons. analytics-flow, ai-teammates and defi-routing. */
  note?: string;
  /** Short points with a check mark, under the buttons; two look best. voice-mobile. */
  points?: string[];
  /** A line under the picture beside the words. ai-teammates. */
  caption?: string;
  /** The line over the logos. decision-spectrum and split-demo. */
  logosTitle?: string;
  /** Customers or partners, shown by name. decision-spectrum, signal-aurora and split-demo. */
  logos?: ArtemisHeroLogo[];
}

"use client";
// @zeus-internal
import { useRef } from "react";
import { motion, useAnimationFrame, useMotionValue, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisHeroContent } from "../content";
const DEFAULT = {
    badge: "Trusted by 8,000+ teams",
    avatars: [{ src: "/assets/artemis/a5badc559b706aa529b9.svg", alt: "" }, { src: "/assets/artemis/a5badc559b706aa529b9.svg", alt: "" }, { src: "/assets/artemis/327d06eee6b741023403.svg", alt: "" }, { src: "/assets/artemis/327d06eee6b741023403.svg", alt: "" }],
    headline: "Search that understands what you mean",
    subhead: "Ask in plain language and Group K ranks the most relevant docs, tickets, and threads \u2014 no keywords or filters required.",
    cta: { label: "Get started", href: "/" },
    secondaryCta: { label: "Request a demo", href: "/" },
    logosTitle: "Searched across the stacks teams trust",
    logos: [{ name: "Workspace" }, { name: "Workspace" }, { name: "Group L" }, { name: "Group F" }, { name: "Group D" }, { name: "Group A" }],
} satisfies ArtemisHeroContent;
/** The icon before each logo name, by slot. */
const ICONS = [
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-layers art:size-5 art:text-muted-foreground/80" aria-hidden="true">
      <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/>
      <path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"/>
      <path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"/>
    </svg>,
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-hexagon art:size-5 art:text-muted-foreground/80" aria-hidden="true">
      <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/>
    </svg>,
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-aperture art:size-5 art:text-muted-foreground/80" aria-hidden="true">
      <circle cx="12" cy="12" r="10"/>
      <path d="m14.31 8 5.74 9.94"/>
      <path d="M9.69 8h11.48"/>
      <path d="m7.38 12 5.74-9.94"/>
      <path d="M9.69 16 3.95 6.06"/>
      <path d="M14.31 16H2.83"/>
      <path d="m16.62 12-5.74 9.94"/>
    </svg>,
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-box art:size-5 art:text-muted-foreground/80" aria-hidden="true">
      <path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z"/>
      <path d="m3.3 7 8.7 5 8.7-5"/>
      <path d="M12 22V12"/>
    </svg>,
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-triangle art:size-5 art:text-muted-foreground/80" aria-hidden="true">
      <path d="M13.73 4a2 2 0 0 0-3.46 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/>
    </svg>,
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-zap art:size-5 art:text-muted-foreground/80" aria-hidden="true">
      <path d="M15.914 4a1.5 1.5 0 00-2.474-1.561l-9 9A1.5 1.5 0 005.5 14h4.002a.5.5 0 01.471.666L8.086 20a1.5 1.5 0 002.475 1.56l9-9A1.5 1.5 0 0018.5 10h-3.997a.5.5 0 01-.472-.667z"/>
    </svg>,
];
export default function HeroSectionsSplitDemo({ content }: { content?: Partial<ArtemisHeroContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const reduce = useReducedMotion();
    const x = useMotionValue(0);
    const paused = useRef(false);
    const track = useRef<HTMLDivElement>(null);
    useAnimationFrame((_time, delta) => {
        if (reduce || paused.current)
            return;
        const width = (track.current?.scrollWidth ?? 0) / 2;
        const next = x.get() - delta * 0.022;
        x.set(width && next <= -width ? next + width : next);
    });
    const reveal = (delay: number) => ({
        initial: { opacity: 0, y: 16 },
        animate: { opacity: 1, y: 0 },
        transition: reduce ? { duration: 0 } : { duration: 0.52, delay, ease: ARTEMIS_EASE_OUT },
    });
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    return (<>
      <div className="art:w-full">
        <section className="art:relative art:w-full art:overflow-hidden art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-2xl art:text-center">
            <motion.span className="art:inline-flex art:items-center art:gap-2 art:rounded-full art:bg-background art:py-1.5 art:pr-4 art:pl-1.5 art:font-medium art:text-foreground art:text-sm" {...reveal(0)}>
              <span className="art:flex">
                {copy.avatars.map((avatar, index) => <motion.img key={index} src={avatar.src} alt={avatar.alt} aria-hidden="true" className="art:-ml-2 art:size-5 art:rounded-full art:ring-2 art:ring-card art:first:ml-0" initial={reduce ? false : { opacity: 0, scale: 0.5, x: -6 }} animate={{ opacity: 1, scale: 1, x: 0 }} transition={reduce ? { duration: 0 } : { type: "spring", stiffness: 480, damping: 24, mass: 0.7, delay: (20 + index * 8) / 100 }}/>)}
              </span>
              {copy.badge}
            </motion.span>
            <motion.h2 className="art:text-balance art:font-sans art:font-medium art:text-5xl art:@min-[768px]/artemis:text-6xl art:leading-[0.94] art:tracking-[-0.055em] art:mt-6 art:text-foreground" {...reveal(0.06)}>
              {copy.headline}
              {copy.headlineAccent ? ` ${copy.headlineAccent}` : null}
            </motion.h2>
            <motion.p className="art:mx-auto art:mt-5 art:max-w-md art:text-pretty art:text-base art:text-muted-foreground art:leading-7" {...reveal(0.12)}>
              {copy.subhead}
            </motion.p>
            <motion.div className="art:mt-8 art:flex art:flex-col art:items-stretch art:justify-center art:gap-3 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-center" {...reveal(0.18)}>
              <motion.a className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0} {...press}>
                {copy.cta.label}
              </motion.a>
              <motion.a className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-card art:text-foreground art:hover:border-border art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={copy.secondaryCta.href} tabIndex={0} {...press}>
                {copy.secondaryCta.label}
              </motion.a>
            </motion.div>
          </div>
          <motion.div className="art:mt-16" {...reveal(0.26)}>
            <p className="art:text-center art:text-muted-foreground/80 art:text-xs">
              {copy.logosTitle}
            </p>
            <div onMouseEnter={() => { paused.current = true; }} onMouseLeave={() => { paused.current = false; }} className="art:mt-5 art:overflow-hidden art:[mask-image:linear-gradient(to_right,transparent,black_8%,black_92%,transparent)]">
              <div className="art:flex art:w-max">
                <motion.div className="art:flex art:w-max art:gap-10" ref={track} style={{ x }}>
                  {[0, 1, 2, 3].flatMap(repeat => copy.logos.map((logo, index) => <span key={`${repeat}-${index}`} className="art:inline-flex art:shrink-0 art:items-center art:gap-2 art:font-semibold art:text-base art:text-muted-foreground/60">
                    {ICONS[index % ICONS.length]}
                    {logo.name}
                  </span>))}
                </motion.div>
              </div>
            </div>
          </motion.div>
        </section>
      </div>
    </>);
}
